class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self._limit_bytes = int(monthly_limit_mib * 1024 * 1024)
        self._used = {}       # month -> bytes counted toward quota
        self._files = {}      # name -> size_bytes

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        if size_bytes <= 0:
            raise ValueError("Upload size must be greater than 0 bytes.")
        if name in self._files:
            raise ValueError(f"A file named {name!r} already exists.")
        current = self._used.get(month, 0)
        if current + size_bytes > self._limit_bytes:
            raise ValueError("Upload would exceed the monthly quota.")
        self._used[month] = current + size_bytes
        self._files[name] = size_bytes

    def delete(self, name: str, month: str) -> None:
        if name not in self._files:
            raise ValueError(f"No file named {name!r} exists.")
        # Deleting does not return quota in the current month,
        # so we simply remove the file record.
        del self._files[name]

    def used_bytes(self, month: str) -> int:
        return self._used.get(month, 0)
